import{_ as t,o as a,c as o,ag as n}from"./chunks/framework.B_zcDAFh.js";const u=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),r={name:"guide/index.md"};function i(s,e,l,h,c,d){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><h2 id="the-four-components" tabindex="-1">The Four Components <a class="header-anchor" href="#the-four-components" aria-label="Permalink to &quot;The Four Components&quot;">​</a></h2><ul><li><strong><a href="./boing-behavior.html">Boing Behavior</a></strong> — attach to a transform. Whenever you move or rotate the object, its rendered position and rotation spring toward the target instead of snapping. Drive it however you want (input, scripts, tweens, animations, etc.) and the bounce just happens.</li><li><strong><a href="./boing-reactor.html">Boing Reactor</a></strong> — a <code>BoingBehavior</code> that <em>also</em> reacts to nearby <a href="./boing-effector.html">Boing Effectors</a> (push points, blasts, wind sources).</li><li><strong><a href="./boing-reactor-field.html">Boing Reactor Field</a></strong> — a 3D grid of reactors that effectors push. Many objects then read the field cheaply through a <a href="./boing-reactor-field-sampler.html">sampler</a> (CPU component) or directly inside the vertex shader (HLSL include or URP/HDRP shader subgraph). Use this instead of giving thousands of objects their own reactor.</li><li><strong><a href="./boing-bones.html">Boing Bones</a></strong> — applies bouncy motion down a bone chain (hair, tails, antennae, jiggly props). Reacts to effectors too.</li></ul><p>All four share a <a href="./shared-boing-params.html">Shared Boing Params</a> asset for tuning oscillation frequency, decay, and other spring parameters in one place.</p><h2 id="getting-help" tabindex="-1">Getting Help <a class="header-anchor" href="#getting-help" aria-label="Permalink to &quot;Getting Help&quot;">​</a></h2><ul><li>Hover any component property in the Inspector — every field carries a tooltip.</li><li>Each <code>Assets/Boing Kit/Examples/</code> subfolder has its own <code>README.txt</code> with setup steps.</li><li>Full online manual: <a href="http://longbunnylabs.com/boing-kit-manual/" target="_blank" rel="noreferrer">http://longbunnylabs.com/boing-kit-manual/</a>.</li><li>Email <a href="mailto:LongBunnyLabs@gmail.com" target="_blank" rel="noreferrer">LongBunnyLabs@gmail.com</a>.</li></ul><h2 id="where-to-go-next" tabindex="-1">Where to Go Next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to Go Next&quot;">​</a></h2><ul><li>Start with <a href="./shared-boing-params.html">Shared Boing Params</a>, then read through each component.</li><li>Known issues: <a href="./faq.html">FAQ</a>.</li></ul>',8)])])}const p=t(r,[["render",i]]);export{u as __pageData,p as default};
